// First, find all sender accounts that have transfers to some common account
// where ALL transfers from that sender to that common account are below 10,000,000
MATCH (sender:Account {_workspace_id: $workspace_id})-[t:TRANSFER]->(common:Account {_workspace_id: $workspace_id})
WITH common, sender, COLLECT(t.amount) as amounts
WHERE ALL(amount IN amounts WHERE amount < 10000000)
WITH common, sender
// Now find the owner of each sender account
MATCH (owner)-[:OWN]->(sender)
WHERE (owner:Person OR owner:Company) AND owner._workspace_id = $workspace_id
WITH common, owner, COUNT(DISTINCT sender) as

